normalized_template:
["opt:-c=from pathlib import Path
for p in Path('sqlglot/dialects').glob('*.py'):
 s=p.read_text()
 if 'ID_VAR_TOKENS' in s or 'def _parse_alias' in s:
  for i,l in enumerate(s.splitlines(),1):
   if 'ID_VAR_TOKENS' in l or 'def _parse_alias' in l: print(p, i, l.strip())", "tool=python"]

