normalized_template:
["opt:-c=import pathlib; terms=('DATEPART','DATENAME','TimeToStr','EXTRACT');
for p in pathlib.Path('tests').rglob('*'):
 if p.is_file():
  try: lines=p.read_text().splitlines()
  except UnicodeDecodeError: continue
  for i,x in enumerate(lines,1):
   if any(t.lower() in x.lower() for t in terms): print(f'{p}:{i}:{x}')", "tool=python"]

