normalized_template:
["opt:-e=
x<-c(-2,0,2); h<-dnorm(x,log=TRUE); d<-c(1,0,-1)
for(y in c(-5,-2,-1,-0.5,0,0.5,1,2,5)){
  t<-h+d*(y-x); cat(sprintf("y=%5.1f  max line idx=%d  val=%.3f\n",y,which.max(t),max(t)))
}", "tool=Rscript"]

